import os
import tarfile

def create_tar(filenames, tarname):
    with tarfile.open(tarname, "w") as tar:
        for filename in filenames:
            tar.add(filename)

def backup(paths):
    all_filenames = []
    for p in paths:
        for dirpath, dirnames, filenames in os.walk(p):
            for f in filenames:
                if f.endswith("txt"):
                    all_filenames.append(os.path.join(dirpath, f))
    tarname = "/tmp/backup.tar"
    create_tar(all_filenames, tarname)
    return tarname

