import tarfile
from PIL import Image
from PIL.ExifTags import TAGS

def get_exif(image_path):
    image = Image.open(image_path)
    exif_data = {}
    info = image._getexif()
    if info:
        for tag, value in info.items():
            decoded = TAGS.get(tag, tag)
            exif_data[decoded] = value
        return exif_data
    else:
        return None

